const responseText = $input.item.json.content[0].text;
const cleaned = responseText
  .replace(/```json\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

const defaults = {
  name: null, email: null, phone: null, source: null,
  pref_beach: null, pref_mountain: null, pref_culture: null,
  pref_unique: null, pref_city: null,
  travel_style: null, trip_budget: null,
  monthly_savings: null, already_saving: null,
  existing_savings: null, savings_instruments: null, cards_owned: null,
  blocker_no: null, blocker_unsure: null, blocker_key: null,
  blocker_date: null, blocker_already: null, blocker_other: null,
  destination_primary: null, destination_alternative: null,
  trip_timeline: null, trip_type: null, booking_details: null, calendly_link: null,
  m1_flights: null, m2_accommodation: null, m3_food: null,
  m4_activities: null, m5_transport: null,
  trigger_moment: null, confidence_score: null, success_visibility: null,
  value_points: null, pain_points: null,
  hot_cold: null, journey_stage: null, persona: null,
  next_action: null, feedback_quote: null, key_quotes: null,
  ai_recommendation: null, follow_up_priority: null,
  sentiment_score: null, objection_type: null, predicted_timeline: null
};

try {
  const extracted = JSON.parse(cleaned);
  return { json: { ...defaults, ...extracted } };
} catch (e) {
  return { json: defaults };
}

const d = $('Parse Response').item.json;
const allRecords = $('Fetch All People').item.json.data || [];
const filename = $('Loop Docs').item.json.name || '';

// Fall back to filename-derived name if Claude couldn't find one
const fallbackName = filename.split('_Session')[0].replace(/_/g, ' ').trim();
const personName = (d.name && d.name.trim()) ? d.name.trim() : fallbackName;

// Helper builders — return undefined (excluded by JSON.stringify) when value is null
function txt(v) {
  return (v !== null && v !== undefined && String(v).trim() !== '')
    ? [{ value: String(v).trim() }]
    : undefined;
}
function num(v) {
  const n = Number(v);
  return (v !== null && v !== undefined && !isNaN(n)) ? [{ value: n }] : undefined;
}
function chk(v) {
  return (v !== null && v !== undefined) ? [{ value: Boolean(v) }] : undefined;
}

function buildValues() {
  const v = {};
  if (personName) v.name = [{ first_name: personName, last_name: '', full_name: personName }];

  // G1 Identity
  const source = txt(d.source); if (source) v.source = source;

  // G2 Travel Preferences
  const pref_beach = chk(d.pref_beach); if (pref_beach !== undefined) v.pref_beach = pref_beach;
  const pref_mountain = chk(d.pref_mountain); if (pref_mountain !== undefined) v.pref_mountain = pref_mountain;
  const pref_culture = chk(d.pref_culture); if (pref_culture !== undefined) v.pref_culture = pref_culture;
  const pref_unique = chk(d.pref_unique); if (pref_unique !== undefined) v.pref_unique = pref_unique;
  const pref_city = chk(d.pref_city); if (pref_city !== undefined) v.pref_city = pref_city;
  const travel_style = txt(d.travel_style); if (travel_style) v.travel_style = travel_style;
  const trip_budget = txt(d.trip_budget); if (trip_budget) v.trip_budget = trip_budget;

  // G3 Financial
  const monthly_savings = num(d.monthly_savings); if (monthly_savings) v.monthly_savings = monthly_savings;
  const already_saving = chk(d.already_saving); if (already_saving !== undefined) v.already_saving = already_saving;
  const existing_savings = txt(d.existing_savings); if (existing_savings) v.existing_savings = existing_savings;
  const savings_instruments = txt(d.savings_instruments); if (savings_instruments) v.savings_instruments = savings_instruments;
  const cards_owned = txt(d.cards_owned); if (cards_owned) v.cards_owned = cards_owned;

  // G4 Blockers
  const blocker_no = chk(d.blocker_no); if (blocker_no !== undefined) v.blocker_no = blocker_no;
  const blocker_unsure = chk(d.blocker_unsure); if (blocker_unsure !== undefined) v.blocker_unsure = blocker_unsure;
  const blocker_key = chk(d.blocker_key); if (blocker_key !== undefined) v.blocker_key = blocker_key;
  const blocker_date = chk(d.blocker_date); if (blocker_date !== undefined) v.blocker_date = blocker_date;
  const blocker_already = chk(d.blocker_already); if (blocker_already !== undefined) v.blocker_already = blocker_already;
  const blocker_other = txt(d.blocker_other); if (blocker_other) v.blocker_other = blocker_other;

  // G5 Current Trip
  const destination_primary = txt(d.destination_primary); if (destination_primary) v.destination_primary = destination_primary;
  const destination_alternative = txt(d.destination_alternative); if (destination_alternative) v.destination_alternative = destination_alternative;
  const trip_timeline = txt(d.trip_timeline); if (trip_timeline) v.trip_timeline = trip_timeline;
  const trip_type = txt(d.trip_type); if (trip_type) v.trip_type = trip_type;
  const booking_details = txt(d.booking_details); if (booking_details) v.booking_details = booking_details;
  const calendly_link = txt(d.calendly_link); if (calendly_link) v.calendly_link = calendly_link;

  // G6 Milestones
  const m1_flights = chk(d.m1_flights); if (m1_flights !== undefined) v.m1_flights = m1_flights;
  const m2_accommodation = chk(d.m2_accommodation); if (m2_accommodation !== undefined) v.m2_accommodation = m2_accommodation;
  const m3_food = chk(d.m3_food); if (m3_food !== undefined) v.m3_food = m3_food;
  const m4_activities = chk(d.m4_activities); if (m4_activities !== undefined) v.m4_activities = m4_activities;
  const m5_transport = chk(d.m5_transport); if (m5_transport !== undefined) v.m5_transport = m5_transport;
  const trigger_moment = txt(d.trigger_moment); if (trigger_moment) v.trigger_moment = trigger_moment;
  const confidence_score = num(d.confidence_score); if (confidence_score) v.confidence_score = confidence_score;
  const success_visibility = txt(d.success_visibility); if (success_visibility) v.success_visibility = success_visibility;

  // G7 JTBD
  const value_points = txt(d.value_points); if (value_points) v.value_points = value_points;
  const pain_points = txt(d.pain_points); if (pain_points) v.pain_points = pain_points;

  // G8 Engagement
  const paid = chk(d.paid); if (paid !== undefined) v.paid = paid;
  const amount = num(d.amount); if (amount) v.amount = amount;
  const payment_date = txt(d.payment_date); if (payment_date) v.payment_date = payment_date;
  const hot_cold = txt(d.hot_cold); if (hot_cold) v.hot_cold = hot_cold;
  const journey_stage = txt(d.journey_stage); if (journey_stage) v.journey_stage = journey_stage;
  const persona = txt(d.persona); if (persona) v.persona = persona;
  const next_action = txt(d.next_action); if (next_action) v.next_action = next_action;
  const feedback_quote = txt(d.feedback_quote); if (feedback_quote) v.feedback_quote = feedback_quote;
  const key_quotes = txt(d.key_quotes); if (key_quotes) v.key_quotes = key_quotes;

  // G9 Actions & Intelligence
  const ai_recommendation = txt(d.ai_recommendation); if (ai_recommendation) v.ai_recommendation = ai_recommendation;
  const follow_up_priority = txt(d.follow_up_priority); if (follow_up_priority) v.follow_up_priority = follow_up_priority;
  const sentiment_score = num(d.sentiment_score); if (sentiment_score) v.sentiment_score = sentiment_score;
  const objection_type = txt(d.objection_type); if (objection_type) v.objection_type = objection_type;
  const predicted_timeline = txt(d.predicted_timeline); if (predicted_timeline) v.predicted_timeline = predicted_timeline;

  return v;
}

const existing = allRecords.find(r => {
  const nameArr = r.values && r.values.name;
  if (!nameArr || !nameArr[0]) return false;
  return (nameArr[0].full_name || '').toLowerCase() === (personName || '').toLowerCase();
});

const values = buildValues();

if (!existing) {
  return {
    json: {
      isNew: 'true',
      body: JSON.stringify({ data: { values } })
    }
  };
}

return {
  json: {
    isNew: 'false',
    recordId: existing.id.record_id,
    body: JSON.stringify({ data: { values } })
  }
};
